const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const version = 'v0.29.4';
const revision = '9596849bcdcefad2133ed484a97a77afd1baa038';
const checksums = 'a2591185d010b1e220e3642b88d968acf79c119611f47af6c9d653a86d57a2e1';
// Verified against the release-attested containers.txt, not mutable registry tags.
const images = {
  squid: '0177ed4bf89e5ec8fdf689619c860d786569050aaa9d8693d434b624b2826b90',
  agent: '5b4e1d01259378592a532ad81d79318a5737fdce548e227db49f3a6ec5aaefd4',
  'api-proxy': '90dfb72976611149f934c4e29147a421faa0429a45d10078ce1527555259ec1a',
  'cli-proxy': 'a892da446103711ccc82c0bfdacb39d9872dd1dc64f69cd4fb4eef811e2e0375',
  'enclave-agent': '2c75f5416ed21570f0b1ba2c509f35e690f52954de550f87579be67e7d2c7ced',
  'enclave-mcp-server': '2bb0fed86e9a7694be0e44c39330d91a95dca1f87e8dfd98df5925c5406df350',
};
const marker = `# Enclave runtime bridge: ${version} (${revision}); generated by .github/aw/inject-enclave-runtime.cjs`;
const hint = `\n\nFor \`awf-enclave enclave_run_agent\`, AWF ${version} sets \`github/gh-aw-firewall\` (\`public\`, not \`trusted\`) to a null per-run bit budget: no finite bit ceiling.
Finite response schemas are still required; free-form strings are reserved for \`trusted\` repositories.
Keep this diagnostic to small enums and booleans with schema cardinality at most 6 and output at most 64 bytes. The 4096-byte task and single-invocation limits remain unchanged. Public sensitivity does not guarantee detailed failure diagnostics.`;

const authenticatedInstall = `set -euo pipefail
install_dir=$(mktemp -d "\${RUNNER_TEMP}/awf-release-install.XXXXXX")
trap 'rm -f "$install_dir/checksums.txt" "$install_dir/release-identity.txt"; rmdir "$install_dir"' EXIT
for asset in checksums.txt release-identity.txt; do
  curl --proto '=https' --proto-redir '=https' -fsSL \\
    "https://github.com/github/gh-aw-firewall/releases/download/${version}/$asset" \\
    -o "$install_dir/$asset"
  gh attestation verify "$install_dir/$asset" --hostname github.com \\
    --repo github/gh-aw-firewall \\
    --signer-workflow github/gh-aw-firewall/.github/workflows/release.yml \\
    --cert-oidc-issuer https://token.actions.githubusercontent.com --deny-self-hosted-runners
done
checksums_sha256=$(sha256sum "$install_dir/checksums.txt" | cut -d ' ' -f1)
test "$checksums_sha256" = ${checksums}
test "$(cat "$install_dir/release-identity.txt")" = "$checksums_sha256  refs/tags/${version}"
bash "\${RUNNER_TEMP}/gh-aw/actions/install_awf_binary.sh" ${version} \\
  --checksums-sha256 "$checksums_sha256" --rootless
`;

const imageTag = [version.slice(1), ...Object.entries(images).map(([name, digest]) => `${name}=sha256:${digest}`)].join(',');
function verifyInjected(lock) {
  const installers = [...lock.matchAll(/^      - name: Install AWF binary\n[\s\S]*?(?=^      - |(?![\s\S]))/gm)];
  assert.equal(installers.length, 2, 'Expected agent and detection installers');
  for (const [step] of installers) {
    assert.match(step, /^        env:\n(?:          [^\n]*\n)*          GH_TOKEN: \$\{\{ github.token \}\}$/m,
      'AWF installer must bind its own GitHub token');
    assert.match(step, /^        env:\n(?:          [^\n]*\n)*          GH_HOST: github\.com$/m,
      'AWF installer must target the public release host');
  }
  assert.equal(lock.split(String.raw`\"imageTag\":\"${imageTag}\"`).length - 1, 2, 'Runtime image pins drifted');
  assert.equal(lock.split(String.raw`\"enclaveDebugPublic\":true`).length - 1, 1, 'Public debug gate drifted');
  assert.equal(lock.split(authenticatedInstall.trimEnd().split('\n').map(part => `          ${part}`).join('\n')).length - 1,
    2, 'Authenticated rootless installers drifted');
  const upload = lock.match(/name: Upload validated public enclave diagnostics or safe collection status\n[\s\S]*?retention-days: ([^\n]+)/);
  assert.equal(upload?.[1], '1', 'Public diagnostics must have fixed one-day retention');
  const manifest = JSON.parse(lock.split('\n')[1].slice('# gh-aw-manifest: '.length));
  assert.equal(manifest.resolution_failures.length, 0, 'Unresolved image/action pins');
  for (const [name, digest] of Object.entries(images)) {
    assert(manifest.containers.some(pin =>
      pin.pinned_image === `ghcr.io/github/gh-aw-firewall/${name}:${version.slice(1)}@sha256:${digest}`),
    'Manifest image pin drifted');
  }
  const downloads = lock.split('\n').filter(line => line.includes('run: bash "${RUNNER_TEMP}/gh-aw/actions/download_docker_images.sh"'));
  assert.equal(downloads.length, 2, 'Image download steps drifted');
  for (const line of downloads) {
    assert(!/ghcr\.io\/github\/gh-aw-firewall\/[a-z-]+:0\.29\.4(?:\s|$)/.test(line),
      'AWF image downloads must use immutable digests');
    assert(line.includes(`ghcr.io/github/gh-aw-firewall/cli-proxy:0.29.4@sha256:${images['cli-proxy']}`),
      'Pinned CLI proxy download missing');
  }
  assert(lock.includes(JSON.stringify(hint).slice(1, -1)), 'Public prompt hint drifted');
}

function inject(lock, source) {
  assert(source.includes(`version: ${version}`) && source.includes(`checksums-sha256: ${checksums}`),
    'Authored AWF version/checksum must match the reviewed bridge');
  const metadata = JSON.parse(lock.split('\n')[0].slice('# gh-aw-metadata: '.length));
  assert.equal(metadata.compiler_version, 'v1.0.1', 'Use the official gh-aw v1.0.1 compiler');
  assert(lock.includes('id: prepare-enclave-diagnostics') && lock.includes('id: collect-enclave-diagnostics'),
    'Compile the authored collector lifecycle first');
  if (lock.includes(marker)) {
    verifyInjected(lock);
    return lock;
  }
  assert(!lock.includes('# Enclave runtime bridge:'), 'Remove a stale bridge by recompiling first');

  let configs = 0;
  lock = lock.replace(/^.*printf '%s\\n' "\{.* > "\$\{RUNNER_TEMP\}\/gh-aw\/awf-config\.json"$/gm, line => {
    assert(line.includes(`releases/download/${version}/`), 'AWF config version drift');
    assert(line.includes(String.raw`\"imageTag\":\"0.29.4\"`), 'Unexpected compiler image configuration');
    configs++;
    line = line.replace(String.raw`\"imageTag\":\"0.29.4\"`, String.raw`\"imageTag\":\"${imageTag}\"`);
    if (line.includes(String.raw`\"enclaves\":`)) {
      assert(line.includes(String.raw`\"isolation\":true`), 'Enclave network isolation must remain enabled');
      line = line.replace(String.raw`\"enclaves\":`, String.raw`\"enclaveDebugPublic\":true,\"enclaves\":`);
    }
    return line;
  });
  assert.equal(configs, 2, 'Expected only agent and threat-detection AWF configs');

  let downloads = 0;
  lock = lock.replace(/^(\s+run: bash "\$\{RUNNER_TEMP\}\/gh-aw\/actions\/download_docker_images\.sh") (.*)$/gm,
    (_, command, args) => {
      downloads++;
      const names = args.includes('/enclave-agent:')
        ? ['cli-proxy', 'agent', 'api-proxy', 'enclave-agent', 'enclave-mcp-server', 'squid']
        : ['cli-proxy', 'agent', 'api-proxy', 'squid'];
      const otherImages = args.split(' ').filter(image => !image.startsWith('ghcr.io/github/gh-aw-firewall/'));
      assert(args.includes(`ghcr.io/github/gh-aw-firewall/agent:${version.slice(1)}`), 'Image download version drift');
      return command + ' ' + [
        ...names.map(name => `ghcr.io/github/gh-aw-firewall/${name}:${version.slice(1)}@sha256:${images[name]}`),
        ...otherImages,
      ].join(' ');
    });
  assert.equal(downloads, 2, 'Expected only agent and detection image downloads');

  let installers = 0;
  const installLine = `        run: bash "\${RUNNER_TEMP}/gh-aw/actions/install_awf_binary.sh" ${version} --checksums-sha256 ${checksums} --rootless`;
  lock = lock.replace(/^      - name: Install AWF binary\n[\s\S]*?(?=^      - |(?![\s\S]))/gm, step => {
    assert(step.includes(installLine), 'Unexpected AWF installer command');
    installers++;
    step = step.replace(installLine,
      `        run: |\n${authenticatedInstall.trimEnd().split('\n').map(part => `          ${part}`).join('\n')}`);
    const env = step.match(/^        env:\n(?:          [^\n]*\n)*/m);
    const bindings = '          GH_HOST: github.com\n          GH_TOKEN: ${{ github.token }}\n';
    if (env) {
      return step.replace(env[0],
        env[0].replace(/^          GH_(?:HOST|TOKEN):[^\n]*\n/gm, '') + bindings);
    }
    return step + '        env:\n' + bindings;
  });
  assert.equal(installers, 2, 'Expected two checksum-pinned rootless installers');

  let hints = 0;
  lock = lock.replace(/^(\s+GH_AW_MCP_CLI_SERVERS_LIST: )(".*")$/gm, (line, prefix, value) => {
    hints++;
    return prefix + JSON.stringify(JSON.parse(value) + hint);
  });
  assert.equal(hints, 1, 'Expected the scoped enclave prompt hint');
  let uploads = 0;
  lock = lock.replace(/(name: Upload validated public enclave diagnostics or safe collection status\n[\s\S]*?retention-days: )[^\n]+/, (_, prefix) => {
    uploads++;
    return prefix + '1';
  });
  assert.equal(uploads, 1, 'Expected the one-day diagnostic upload');

  const manifestLine = lock.split('\n')[1];
  const manifest = JSON.parse(manifestLine.slice('# gh-aw-manifest: '.length));
  const prefix = 'ghcr.io/github/gh-aw-firewall/';
  manifest.containers = [
    ...Object.entries(images).map(([name, digest]) => {
      const image = `${prefix}${name}:${version.slice(1)}`;
      return { image, digest: `sha256:${digest}`, pinned_image: `${image}@sha256:${digest}` };
    }),
    ...manifest.containers.filter(container => !container.image.startsWith(prefix)),
  ];
  manifest.resolution_failures = manifest.resolution_failures.filter(failure =>
    !(Object.hasOwn(images, failure.repo.slice(prefix.length)) && failure.repo.startsWith(prefix)
      && failure.ref === version.slice(1) && failure.error_type === 'container_pin_not_found'));
  assert.equal(manifest.resolution_failures.length, 0, 'Unresolved pins must not be hidden');
  lock = lock.replace(manifestLine, '# gh-aw-manifest: ' + JSON.stringify(manifest));
  lock = lock.replace('# This file was automatically generated', marker + '\n# This file was automatically generated');
  verifyInjected(lock);
  return lock;
}

module.exports = { inject, images, version, revision, checksums };
if (require.main === module) {
  const root = path.resolve(__dirname, '../..');
  const base = path.join(root, '.github/workflows/roadmap-triage-enclave');
  const file = base + '.lock.yml';
  const current = fs.readFileSync(file, 'utf8');
  const updated = inject(current, fs.readFileSync(base + '.md', 'utf8'));
  if (process.argv.includes('--check')) {
    assert.equal(current, updated, 'Recompile and inject the enclave runtime bridge');
  } else {
    fs.writeFileSync(file, updated);
  }
}
